content.text:
{
  "primary_meaning": "Spiritual unfaithfulness or idolatry (covenant adultery against God, often depicted as Israel or the people of God acting as a harlot by pursuing false gods or worldly powers)",
  "primary_basis": [
    "Hosea 1–3 (esp. Hosea 2:2–13)",
    "Jeremiah 2:20–25; 3:1–9",
    "Ezekiel 16:15–43; 23:1–49",
    "Revelation 17:1–6; 18:3; 19:2",
    "Isaiah 1:21; 57:3–8"
  ],
  "alternatives": [
    {
      "meaning": "Literal sexual immorality or cultic prostitution without metaphor (treated as straightforward ethical prohibition rather than symbol)",
      "basis": [
        "1 Corinthians 6:9–20",
        "Galatians 5:19",
        "Leviticus 18–20",
        "Deuteronomy 22–23"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Political alliances or dependence on foreign nations (treated as a form of unfaithfulness overlapping with but distinct from pure idolatry)",
      "basis": [
        "Ezekiel 16:26–29; 23:5–21",
        "Hosea 7:11; 8:9",
        "Isaiah 30:1–7; 31:1"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Apostate or corrupt religious institution (e.g., the harlot as the false church or Babylon as ecclesiastical Rome in historicist Protestant readings)",
      "basis": [
        "Revelation 17–18",
        "interpretive tradition linking to 2 Thessalonians 2 and papal critiques"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Economic exploitation, luxury, or commercial seduction of the nations (especially Babylon the great as imperial commerce)",
      "basis": [
        "Revelation 18:3, 9–19",
        "Ezekiel 27–28 (Tyre parallel)"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "The prophetic metaphor of whoredom for idolatry/covenant breach is the dominant and long-settled symbolic reading across mainstream Jewish and Christian interpretation of the relevant texts; literal sexual readings coexist but are not the primary symbolic assignment. Secondary applications (political, institutional, economic) remain subsidiary elaborations of the same unfaithfulness motif rather than fully independent meanings."
}
